-- Candidate-only, immutable identities for the existing saved-draft wire.
-- Old scoring catalogs, adoption requests, activations and retirements remain unchanged.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';

create table private.questionnaire_validation_catalog (
 validation_catalog_hash text primary key check(validation_catalog_hash ~ '^[a-f0-9]{64}$'),
 scoring_catalog_hash text not null references private.questionnaire_rule_catalog(catalog_hash) on delete restrict,
 form_key text not null,
 form_version text not null,
 rule_version text not null,
 validation_version text not null,
 canonical_json text not null check(octet_length(canonical_json) between 2 and 2097152),
 manifest_json jsonb not null,
 created_at timestamptz not null default clock_timestamp(),
 unique(form_key,form_version,rule_version,validation_version),
 check(validation_catalog_hash=encode(sha256(convert_to(canonical_json,'UTF8')),'hex')),
 check(canonical_json::jsonb=manifest_json),
 check((jsonb_typeof(manifest_json)='object'
  and manifest_json-array['schemaVersion','candidateOnly','validationBoundary','validationVersion','formKey','formVersion','ruleVersion','scoringCatalogHash','wire','exactQuestionIds','items','context','measurement','issueRules','resultPolicy']='{}'::jsonb
  and manifest_json ?& array['schemaVersion','candidateOnly','validationBoundary','validationVersion','formKey','formVersion','ruleVersion','scoringCatalogHash','wire','exactQuestionIds','items','context','measurement','issueRules','resultPolicy']
  and manifest_json->>'schemaVersion'='questionnaire-validation-catalog.v1'
  and manifest_json->'candidateOnly'='true'::jsonb
  and manifest_json->>'validationBoundary'='database-draft-wire'
  and manifest_json->>'validationVersion'=validation_version
  and manifest_json->>'formKey'=form_key and manifest_json->>'formVersion'=form_version
  and manifest_json->>'ruleVersion'=rule_version and manifest_json->>'scoringCatalogHash'=scoring_catalog_hash
  and jsonb_typeof(manifest_json->'wire')='object'
  and jsonb_typeof(manifest_json->'exactQuestionIds')='array'
  and jsonb_typeof(manifest_json->'items')='array' and jsonb_typeof(manifest_json->'context')='array'
  and jsonb_typeof(manifest_json->'issueRules')='array' and jsonb_typeof(manifest_json->'resultPolicy')='object') is true)
);
create table private.questionnaire_readiness_catalog (
 bundle_hash text primary key check(bundle_hash ~ '^[a-f0-9]{64}$'),
 scoring_catalog_hash text not null references private.questionnaire_rule_catalog(catalog_hash) on delete restrict,
 validation_catalog_hash text not null references private.questionnaire_validation_catalog(validation_catalog_hash) on delete restrict,
 form_key text not null,
 form_version text not null,
 rule_version text not null,
 validation_version text not null,
 canonical_json text not null check(octet_length(canonical_json) between 2 and 16384),
 manifest_json jsonb not null,
 created_at timestamptz not null default clock_timestamp(),
 unique(form_key,form_version,rule_version,validation_version),
 check(bundle_hash=encode(sha256(convert_to(canonical_json,'UTF8')),'hex')),
 check(canonical_json::jsonb=manifest_json),
 check((jsonb_typeof(manifest_json)='object'
  and manifest_json-array['schemaVersion','candidateOnly','formKey','formVersion','ruleVersion','scoringCatalogHash','validationCatalogHash','validationVersion','validationBoundary','scope']='{}'::jsonb
  and manifest_json ?& array['schemaVersion','candidateOnly','formKey','formVersion','ruleVersion','scoringCatalogHash','validationCatalogHash','validationVersion','validationBoundary','scope']
  and manifest_json->>'schemaVersion'='questionnaire-readiness-bundle.v1'
  and manifest_json->'candidateOnly'='true'::jsonb
  and manifest_json->>'validationBoundary'='database-draft-wire'
  and manifest_json->>'scope'='validation-and-candidate-scoring'
  and manifest_json->>'formKey'=form_key and manifest_json->>'formVersion'=form_version
  and manifest_json->>'ruleVersion'=rule_version and manifest_json->>'scoringCatalogHash'=scoring_catalog_hash
  and manifest_json->>'validationCatalogHash'=validation_catalog_hash
  and manifest_json->>'validationVersion'=validation_version) is true)
);
create index questionnaire_validation_scoring_idx on private.questionnaire_validation_catalog(scoring_catalog_hash);
create index questionnaire_readiness_scoring_idx on private.questionnaire_readiness_catalog(scoring_catalog_hash);
create index questionnaire_readiness_validation_idx on private.questionnaire_readiness_catalog(validation_catalog_hash);

create function private.questionnaire_readiness_catalog_binding()
returns trigger language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from private.questionnaire_rule_catalog s
  where s.catalog_hash=new.scoring_catalog_hash and s.form_key=new.form_key
   and s.form_version=new.form_version and s.rule_version=new.rule_version) then
  raise exception using errcode='23514',message='candidate catalog identity mismatch';
 end if;
 if tg_table_name='questionnaire_readiness_catalog' and not exists(
  select 1 from private.questionnaire_validation_catalog v where v.validation_catalog_hash=new.validation_catalog_hash
   and v.scoring_catalog_hash=new.scoring_catalog_hash and v.form_key=new.form_key
   and v.form_version=new.form_version and v.rule_version=new.rule_version and v.validation_version=new.validation_version) then
  raise exception using errcode='23514',message='candidate catalog identity mismatch';
 end if;
 return new;
end;$$;
revoke all on function private.questionnaire_readiness_catalog_binding() from public,anon,authenticated,service_role;
do $$declare name text;begin
 foreach name in array array['questionnaire_validation_catalog','questionnaire_readiness_catalog'] loop
  execute format('alter table private.%I enable row level security',name);
  execute format('alter table private.%I force row level security',name);
  execute format('revoke all on table private.%I from public,anon,authenticated,service_role',name);
  execute format('create trigger %I before update or delete on private.%I for each row execute function private.prevent_append_only_mutation()',name||'_immutable',name);
  execute format('create trigger %I before insert on private.%I for each row execute function private.questionnaire_readiness_catalog_binding()',name||'_binding',name);
 end loop;
end;$$;

